47	+/* ============================ Đi dạo: lõi bản đồ va chạm 2D ============================
48	+   Thuần toán học: không import three, không import CONFIG, không đụng DOM. Task sau dựng vùng / vật cản từ cảnh rồi gọi các hàm ở đây.
49	+   - Nhân vật là hình tròn bán kính `radius` trên mặt bằng (x, z). Tâm phải nằm trong một vùng mở (`StZone`) và cách mọi vật cản ít nhất `radius`.
50	+   - Vùng chữ nhật, thứ tự mảng là thứ tự ưu tiên khi chồng nhau (vùng đầu tiên chứa điểm quyết định cao độ đứng). Vùng có `gate` thì cổng đóng coi như không có.
51	+   - Vật cản chữ nhật hoặc tròn; có `top` là tường thấp (chặn khi chân thấp hơn `top`, nhảy qua được), vắng `top` là tường cao vô hạn.
52	+   - Chỉ mục lưới đều (ô STC m) để tra vật cản gần một điểm không phải quét hết ~8 000 nhà; vật cản phủ quá nhiều ô để riêng một danh sách "lớn", tra tuyến tính.
53	+   - stMove / stValid chạy mỗi khung: không cấp phát (D-018). */
54	+
55	+export interface StRect { x0: number; x1: number; z0: number; z1: number }
56	+export interface StZone extends StRect { id: string; y: (x: number, z: number) => number; gate?: string }   // y: cao độ đứng tại (x, z), m
57	+export interface StSolid { kind: 'rect' | 'circle'; x0?: number; x1?: number; z0?: number; z1?: number; cx?: number; cz?: number; r?: number; top?: number }   // top: m trên cao độ đứng; vắng = cao vô hạn
58	+export interface StMap { zones: StZone[]; solids: StSolid[]; radius: number; closed: Set<string> }
59	+
60	+/* Chỉ mục lưới, giữ trong map nhưng không lộ ra kiểu công khai */
61	+interface StIndex { cells: Map<number, number[]>; big: number[] }
62	+interface StMapI extends StMap { idx: StIndex }
63	+
64	+const STC = 16;          // cạnh ô lưới, m (nhà ven sông 10–40 m, mỗi nhà phủ vài ô)
65	+const ST_BIG = 64;       // vật cản phủ hơn số ô này thì vào danh sách "lớn"
66	+const ST_OFF = 32768;    // dời chỉ số ô về số dương để ghép khóa (đủ cho ±524 km)
67	+const stKey = (ix: number, iz: number): number => (ix + ST_OFF) * 65536 + (iz + ST_OFF);
68	+
69	+/* Thêm một vật cản (chỉ số i trong map.solids) vào lưới theo hộp bao của nó */
70	+function stIndexOne(idx: StIndex, s: StSolid, i: number): void {
71	+  const x0 = s.kind === 'circle' ? s.cx - s.r : s.x0, x1 = s.kind === 'circle' ? s.cx + s.r : s.x1;
72	+  const z0 = s.kind === 'circle' ? s.cz - s.r : s.z0, z1 = s.kind === 'circle' ? s.cz + s.r : s.z1;
73	+  const ix0 = Math.floor(x0 / STC), ix1 = Math.floor(x1 / STC), iz0 = Math.floor(z0 / STC), iz1 = Math.floor(z1 / STC);
74	+  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > ST_BIG) { idx.big.push(i); return; }
75	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
76	+    const k = stKey(ix, iz); let list = idx.cells.get(k);
77	+    if (!list) { list = []; idx.cells.set(k, list); }
78	+    list.push(i);
79	+  }
80	+}
81	+
82	+export function stMakeMap(zones: StZone[], solids: StSolid[], radius: number): StMap {
83	+  const map: StMapI = { zones, solids: [], radius, closed: new Set<string>(), idx: { cells: new Map<number, number[]>(), big: [] } };
84	+  stAddSolids(map, solids);
85	+  return map;
86	+}
87	+
88	+/* Thêm vật cản lúc chạy (nhà thu từ cảnh, Task 6); lưới cập nhật theo */
89	+export function stAddSolids(map: StMap, more: StSolid[]): void {
90	+  const idx = (map as StMapI).idx;
91	+  for (const s of more) { map.solids.push(s); stIndexOne(idx, s, map.solids.length - 1); }
92	+}
93	+
94	+export function stSetGate(map: StMap, gate: string, closed: boolean): void {
95	+  if (closed) map.closed.add(gate); else map.closed.delete(gate);
96	+}
97	+
98	+export function stZoneAt(map: StMap, x: number, z: number): StZone | null {
99	+  const zs = map.zones;
100	+  for (let i = 0; i < zs.length; i++) {
101	+    const zn = zs[i];
102	+    if (x < zn.x0 || x > zn.x1 || z < zn.z0 || z > zn.z1) continue;
103	+    if (zn.gate !== undefined && map.closed.has(zn.gate)) continue;
104	+    return zn;
105	+  }
106	+  return null;
107	+}
108	+
109	+export function stGroundY(map: StMap, x: number, z: number): number {
110	+  const zn = stZoneAt(map, x, z);
111	+  return zn ? zn.y(x, z) : NaN;
112	+}
113	+
114	+/* Hình tròn tâm (x, z) bán kính R có chạm vật cản s không (khoảng cách < R) */
115	+function stHitOne(s: StSolid, x: number, z: number, R: number, feet: number): boolean {
116	+  if (s.top !== undefined && feet >= s.top) return false;   // chân đã cao hơn tường thấp
117	+  if (s.kind === 'circle') { const ddx = x - s.cx, ddz = z - s.cz, rr = s.r + R; return ddx * ddx + ddz * ddz < rr * rr; }
118	+  const ddx = s.x0 - x > 0 ? s.x0 - x : x - s.x1 > 0 ? x - s.x1 : 0;
119	+  const ddz = s.z0 - z > 0 ? s.z0 - z : z - s.z1 > 0 ? z - s.z1 : 0;
120	+  return ddx * ddx + ddz * ddz < R * R;
121	+}
122	+
123	+/* Có vật cản nào trong bán kính map.radius quanh (x, z) không — chỉ tra các ô lưới phủ hình tròn + danh sách lớn */
124	+function stHit(map: StMap, x: number, z: number, feet: number): boolean {
125	+  const idx = (map as StMapI).idx, sol = map.solids, R = map.radius;
126	+  const big = idx.big;
127	+  for (let i = 0; i < big.length; i++) if (stHitOne(sol[big[i]], x, z, R, feet)) return true;
128	+  const ix0 = Math.floor((x - R) / STC), ix1 = Math.floor((x + R) / STC), iz0 = Math.floor((z - R) / STC), iz1 = Math.floor((z + R) / STC);
129	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
130	+    const list = idx.cells.get(stKey(ix, iz));
131	+    if (!list) continue;
132	+    for (let i = 0; i < list.length; i++) if (stHitOne(sol[list[i]], x, z, R, feet)) return true;
133	+  }
134	+  return false;
135	+}
136	+
137	+/* feet: độ cao chân trên cao độ đứng, m; Infinity = bỏ qua mọi tường thấp */
138	+export function stValid(map: StMap, x: number, z: number, feet: number): boolean {
139	+  return stZoneAt(map, x, z) !== null && !stHit(map, x, z, feet);
140	+}
141	+
142	+/* Đi (dx, dz) từ (x, z), kết quả vào out. Chia bước con ≤ radius / 2 nên vật cản phồng theo bán kính (dày ≥ 2·radius) không thể bị nhảy qua.
143	+   Mỗi bước con: thử cả hai trục, rồi chỉ x, rồi chỉ z (trượt dọc tường), không được thì dừng.
144	+   Điểm xuất phát nằm trong tường thấp (vừa đáp xuống giữa tường) thì bước này bỏ qua tường thấp để thoát ra, không bị kẹt. */
145	+export function stMove(map: StMap, x: number, z: number, dx: number, dz: number, feet: number, out: { x: number; z: number }): void {
146	+  let cx = x, cz = z;
147	+  const len = Math.sqrt(dx * dx + dz * dz);
148	+  if (len > 0) {
149	+    const f = !stValid(map, x, z, feet) && stValid(map, x, z, Infinity) ? Infinity : feet;
150	+    const n = Math.max(1, Math.ceil(len / (map.radius * 0.5)));
151	+    const sx = dx / n, sz = dz / n;
152	+    for (let i = 0; i < n; i++) {
153	+      if (stValid(map, cx + sx, cz + sz, f)) { cx += sx; cz += sz; }
154	+      else if (sx !== 0 && stValid(map, cx + sx, cz, f)) cx += sx;
155	+      else if (sz !== 0 && stValid(map, cx, cz + sz, f)) cz += sz;
156	+      else break;
157	+    }
158	+  }
159	+  out.x = cx; out.z = cz;
160	+}
161	+
162	+/* Điểm hợp lệ gần nhất (chân trên mặt đứng, tường thấp tính là chặn): vòng tròn nở dần mỗi 0,2 m, tối đa 80 m.
163	+   Dùng cho sơ tán và điểm xuất phát, không gọi mỗi khung (trường hợp xấu nhất vài triệu lần thử). */
164	+const ST_NEAR_STEP = 0.2;   // bước nở vòng và khoảng cách điểm trên vòng, m
165	+const ST_NEAR_MAX = 80;     // bán kính tìm tối đa, m
166	+export function stNearestValid(map: StMap, x: number, z: number, out: { x: number; z: number }): boolean {
167	+  if (stValid(map, x, z, 0)) { out.x = x; out.z = z; return true; }
168	+  const rings = Math.round(ST_NEAR_MAX / ST_NEAR_STEP);
169	+  for (let k = 1; k <= rings; k++) {
170	+    const d = k * ST_NEAR_STEP, n = Math.ceil(2 * Math.PI * d / ST_NEAR_STEP);
171	+    for (let j = 0; j < n; j++) {
172	+      const a = j * 2 * Math.PI / n, px = x + d * Math.cos(a), pz = z + d * Math.sin(a);
173	+      if (stValid(map, px, pz, 0)) { out.x = px; out.z = pz; return true; }
174	+    }
175	+  }
176	+  return false;
177	+}
178	+
179	+/* Tham số t (0..1) nơi đoạn a + t·d đi vào vật cản s (hình thật, không phồng theo bán kính); 2 = không chạm */
180	+function stSegEnter(s: StSolid, ax: number, az: number, dx: number, dz: number): number {
181	+  if (s.kind === 'circle') {
182	+    const fx = ax - s.cx, fz = az - s.cz, c = fx * fx + fz * fz - s.r * s.r;
183	+    if (c <= 0) return 0;                                   // xuất phát trong cột
184	+    const a = dx * dx + dz * dz, b = 2 * (fx * dx + fz * dz);
185	+    if (a === 0) return 2;
186	+    const disc = b * b - 4 * a * c;
187	+    if (disc < 0) return 2;
188	+    const t = (-b - Math.sqrt(disc)) / (2 * a);
189	+    return t >= 0 && t <= 1 ? t : 2;
190	+  }
191	+  let tmin = -Infinity, tmax = Infinity;
192	+  if (dx === 0) { if (ax < s.x0 || ax > s.x1) return 2; }
193	+  else { let t1 = (s.x0 - ax) / dx, t2 = (s.x1 - ax) / dx; if (t1 > t2) { const q = t1; t1 = t2; t2 = q; } if (t1 > tmin) tmin = t1; if (t2 < tmax) tmax = t2; }
194	+  if (dz === 0) { if (az < s.z0 || az > s.z1) return 2; }
195	+  else { let t1 = (s.z0 - az) / dz, t2 = (s.z1 - az) / dz; if (t1 > t2) { const q = t1; t1 = t2; t2 = q; } if (t1 > tmin) tmin = t1; if (t2 < tmax) tmax = t2; }
196	+  if (tmax < tmin || tmax < 0 || tmin > 1) return 2;
197	+  return tmin > 0 ? tmin : 0;
198	+}
199	+
200	+/* Phần (0..1) của đoạn a→b đi được trước khi chạm vật cản cao vô hạn hoặc ra khỏi mọi vùng mở (cho camera). Không cấp phát. */
201	+const ST_EPS = 1e-7;   // dung sai khi xét điểm nằm trên cạnh chung hai vùng, m
202	+export function stSegClear(map: StMap, ax: number, az: number, bx: number, bz: number): number {
203	+  const dx = bx - ax, dz = bz - az;
204	+  /* 1) vùng: đi theo chuỗi vùng mở chứa điểm hiện tại, mỗi lần nhảy tới chỗ ra xa nhất */
205	+  let t = 0, tz = 0;
206	+  for (let it = 0; it < 64; it++) {
207	+    const px = ax + dx * t, pz = az + dz * t;
208	+    let best = -1;
209	+    for (let i = 0; i < map.zones.length; i++) {
210	+      const zn = map.zones[i];
211	+      if (px < zn.x0 - ST_EPS || px > zn.x1 + ST_EPS || pz < zn.z0 - ST_EPS || pz > zn.z1 + ST_EPS) continue;
212	+      if (zn.gate !== undefined && map.closed.has(zn.gate)) continue;
213	+      const ex = dx > 0 ? (zn.x1 - ax) / dx : dx < 0 ? (zn.x0 - ax) / dx : Infinity;
214	+      const ez = dz > 0 ? (zn.z1 - az) / dz : dz < 0 ? (zn.z0 - az) / dz : Infinity;
215	+      const e = ex < ez ? ex : ez;
216	+      if (e > best) best = e;
217	+    }
218	+    if (best < 0) { tz = t; break; }                        // không vùng nào chứa điểm (chỉ xảy ra khi xuất phát ngoài vùng)
219	+    if (best >= 1) { tz = 1; break; }
220	+    if (best <= t + 1e-9) { tz = t; break; }                // không vùng nào đi tiếp được
221	+    t = best; tz = t;
222	+  }
223	+  /* 2) vật cản cao vô hạn trong hộp bao đoạn; hộp quá lớn thì quét hết */
224	+  let ts = tz;
225	+  const sol = map.solids, idx = (map as StMapI).idx;
226	+  const ix0 = Math.floor(Math.min(ax, bx) / STC), ix1 = Math.floor(Math.max(ax, bx) / STC), iz0 = Math.floor(Math.min(az, bz) / STC), iz1 = Math.floor(Math.max(az, bz) / STC);
227	+  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > sol.length) {
228	+    for (let i = 0; i < sol.length; i++) { const s = sol[i]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
229	+    return ts;
230	+  }
231	+  const big = idx.big;
232	+  for (let i = 0; i < big.length; i++) { const s = sol[big[i]]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
233	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
234	+    const list = idx.cells.get(stKey(ix, iz));
235	+    if (!list) continue;
236	+    for (let i = 0; i < list.length; i++) { const s = sol[list[i]]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
237	+  }
238	+  return ts;
239	+}
240	diff --git a/tests/stroll-unit/map.test.ts b/tests/stroll-unit/map.test.ts
241	new file mode 100644
242	index 0000000..8469534
243	--- /dev/null
244	+++ b/tests/stroll-unit/map.test.ts
245	@@ -0,0 +1,239 @@
246	+/* ===== Đi dạo: test lõi bản đồ va chạm 2D (src/explore/stroll/map.ts) =====
247	+   Bản đồ tự dựng: hai vùng chữ nhật kề cạnh (A tây, B đông), một vùng có cổng G, một nhà chữ nhật dày 14 m,
248	+   một cột tròn, một tường thấp cao 0,9 m. Fuzz kiểm điểm cuối mỗi stMove bằng oracle viết riêng ở đây (quét tuyến tính, không dùng lưới của map.ts). */
249	+import { test } from 'node:test';
250	+import assert from 'node:assert/strict';
251	+import { stMakeMap, stAddSolids, stSetGate, stZoneAt, stGroundY, stValid, stMove, stNearestValid, stSegClear, type StZone, type StSolid, type StMap } from '../../src/explore/stroll/map.ts';
252	+
253	+const R = 0.35;   // bán kính nhân vật, m
254	+
255	+/* mulberry32 riêng: map test không kéo three vào */
256	+function mulberry(seed: number) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
257	+
258	+const HOUSE: StSolid = { kind: 'rect', x0: 10, x1: 24, z0: -5, z1: 5 };          // nhà dày 14 m theo x
259	+const COLUMN: StSolid = { kind: 'circle', cx: -20, cz: 0, r: 1 };                 // cột tròn
260	+const LOW: StSolid = { kind: 'rect', x0: -40, x1: -39.7, z0: -15, z1: 15, top: 0.9 };   // tường thấp 0,9 m
261	+
262	+function makeZones(): StZone[] {
263	+  return [
264	+    { id: 'A', x0: -50, x1: 0, z0: -20, z1: 20, y: () => 2.5 },
265	+    { id: 'B', x0: 0, x1: 50, z0: -20, z1: 20, y: (x) => 2.6 + x * 0.001 },
266	+    { id: 'G', x0: 50, x1: 60, z0: -5, z1: 5, y: () => 3, gate: 'span' },
267	+  ];
268	+}
269	+function makeMap(): StMap { return stMakeMap(makeZones(), [HOUSE, COLUMN, LOW], R); }
270	+
271	+/* ---- oracle độc lập ---- */
272	+function oInZone(m: StMap, x: number, z: number): boolean {
273	+  for (const zn of m.zones) { if (zn.gate && m.closed.has(zn.gate)) continue; if (x >= zn.x0 && x <= zn.x1 && z >= zn.z0 && z <= zn.z1) return true; }
274	+  return false;
275	+}
276	+function oDist(s: StSolid, x: number, z: number): number {
277	+  if (s.kind === 'circle') return Math.hypot(x - s.cx, z - s.cz) - s.r;
278	+  const dx = Math.max(s.x0 - x, 0, x - s.x1), dz = Math.max(s.z0 - z, 0, z - s.z1);
279	+  return Math.hypot(dx, dz);
280	+}
281	+/* lowToo = true: tính cả tường thấp theo feet */
282	+function oOk(m: StMap, x: number, z: number, feet: number, lowToo: boolean): boolean {
283	+  if (!oInZone(m, x, z)) return false;
284	+  for (const s of m.solids) {
285	+    if (s.top !== undefined && (!lowToo || feet >= s.top)) continue;
286	+    if (oDist(s, x, z) < m.radius - 1e-6) return false;
287	+  }
288	+  return true;
289	+}
290	+
291	+const out = { x: 0, z: 0 };
292	+
293	+test('stValid: trong vùng xa vật cản, sát mép nhà 0,34 / 0,36 m, ngoài vùng', () => {
