443	+    const startOkLow = oOk(m, x, z, feet, true);
444	+    stMove(m, x, z, Math.cos(heading) * len, Math.sin(heading) * len, feet, out);
445	+    if (!oOk(m, out.x, out.z, feet, false)) { bad++; if (!first) first = `bước ${i}: (${x},${z}) + ${len} → (${out.x},${out.z})`; }
446	+    if (startOkLow && !oOk(m, out.x, out.z, feet, true)) { badLow++; if (!first) first = `tường thấp, bước ${i}: (${x},${z}) → (${out.x},${out.z}) feet ${feet}`; }
447	+    if (!stValid(m, out.x, out.z, Infinity) && oOk(m, out.x, out.z, feet, false)) { bad++; if (!first) first = `stValid lệch oracle ở (${out.x},${out.z})`; }
448	+    x = out.x; z = out.z;
449	+  }
450	+  return { bad, badLow, first };
451	+}
452	+
453	+test('fuzz 200 000 bước ngẫu nhiên (bước 0–3 m, feet 0 hoặc 1,2): không điểm cuối nào vi phạm', () => {
