417	+/* bản đồ fuzz: thêm nhiều nhà / cột ngẫu nhiên để có góc, khe hẹp, chỗ chồng nhau */
418	+function fuzzMap(rnd: () => number): StMap {
419	+  const m = makeMap();
420	+  const more: StSolid[] = [];
421	+  for (let i = 0; i < 60; i++) {
422	+    const x = -50 + rnd() * 110, z = -20 + rnd() * 40;
423	+    if (rnd() < 0.6) { const w = 0.2 + rnd() * 6, d = 0.2 + rnd() * 6; more.push({ kind: 'rect', x0: x, x1: x + w, z0: z, z1: z + d, top: rnd() < 0.2 ? 0.6 + rnd() * 0.3 : undefined }); }
424	+    else more.push({ kind: 'circle', cx: x, cz: z, r: 0.1 + rnd() * 2, top: rnd() < 0.2 ? 0.8 : undefined });
425	+  }
426	+  stAddSolids(m, more);
427	+  return m;
428	+}
