430	+function runFuzz(seed: number, steps: number, maxStep: number) {
431	+  const rnd = mulberry(seed);
432	+  const m = fuzzMap(rnd);
433	+  let x = -45, z = 18, heading = 0, bad = 0, badLow = 0, first = '';
434	+  if (!stNearestValid(m, x, z, out)) throw new Error('không có điểm xuất phát');
435	+  x = out.x; z = out.z;
436	+  for (let i = 0; i < steps; i++) {
437	+    if (rnd() < 0.05) heading = rnd() * Math.PI * 2;          // giữ hướng nhiều bước để áp sát và trượt dọc tường
438	+    if (rnd() < 0.002) {                                       // đóng / mở cổng, sơ tán nếu đang đứng trong vùng bị đóng
439	+      stSetGate(m, 'span', !m.closed.has('span'));
440	+      if (!oOk(m, x, z, 0, false)) { assert.ok(stNearestValid(m, x, z, out)); x = out.x; z = out.z; }
441	+    }
442	+    const len = rnd() * maxStep, feet = rnd() < 0.5 ? 0 : 1.2;
443	+    const startOkLow = oOk(m, x, z, feet, true);
444	+    stMove(m, x, z, Math.cos(heading) * len, Math.sin(heading) * len, feet, out);
445	+    if (!oOk(m, out.x, out.z, feet, false)) { bad++; if (!first) first = `bước ${i}: (${x},${z}) + ${len} → (${out.x},${out.z})`; }
446	+    if (startOkLow && !oOk(m, out.x, out.z, feet, true)) { badLow++; if (!first) first = `tường thấp, bước ${i}: (${x},${z}) → (${out.x},${out.z}) feet ${feet}`; }
447	+    if (!stValid(m, out.x, out.z, Infinity) && oOk(m, out.x, out.z, feet, false)) { bad++; if (!first) first = `stValid lệch oracle ở (${out.x},${out.z})`; }
448	+    x = out.x; z = out.z;
449	+  }
450	+  return { bad, badLow, first };
451	+}
